import sys
from collections import defaultdict

def isEulerCircuit(V, adj):
    # Check connectivity of non-isolated vertices
    # First, find all vertices with degree > 0
    degrees = [0] * (V + 1)
    for u in range(1, V + 1):
        degrees[u] = len(adj[u])

    # Find a starting node with degree > 0
    start_node = -1
    for i in range(1, V + 1):
        if degrees[i] > 0:
            start_node = i
            break

    # If no edges exist, it's considered a circuit (trivial)
    if start_node == -1:
        return 2

    # BFS/DFS to check connectivity among vertices with degree > 0
    visited = set()
    stack = [start_node]
    while stack:
        u = stack.pop()
        if u not in visited:
            visited.add(u)
            for v in adj[u]:
                if v not in visited:
                    stack.append(v)

    # Check if all vertices with degree > 0 are visited
    for i in range(1, V + 1):
      if degrees[i] > 0 and i not in visited:
          return 0

    # Count vertices with odd degrees
    odd_degree_count = 0
    for i in range(1, V + 1):
       if degrees[i] % 2 != 0:
           odd_degree_count += 1

    if odd_degree_count == 0:
        return 2
    elif odd_degree_count == 2:
        return 1
    else:
        return 0

